<script setup lang="ts">
import {externalSubscriptionSchema} from '@brightloop/shared'
interface External { id:string;name:string;amount:number;interval:string;nextRenewal:string|null;status:string;category?:string;usage?:string;importance?:number;purpose?:string;managementUrl:string;notes:string }
const api=useApi(),toast=useToast()
const {data,error,status,refresh}=useFetch<{items:External[];totals:{monthly:number;yearly:number;active:number}}>('/api/external-subscriptions')
const open=ref(false),editing=ref(''),busy=ref(false),formError=ref(''),search=ref(''),filter=ref('all')
const selected=ref<External|null>(null),mode=ref<'details'|'edit'>('edit'),removing=ref<External|null>(null)
const filters=[{label:'All',value:'all'},{label:'Upcoming',value:'upcoming'},{label:'Active',value:'active'},{label:'Planned / Interested',value:'planned'},{label:'Inactive',value:'inactive'}]
const statusLabel=(s:string)=>({ACTIVE:'Active',PLANNED:'Planned',INTERESTED:'Interested',INACTIVE:'Inactive',CANCELLED:'Inactive'} as Record<string,string>)[s]||s
const visible=computed(()=>{const now=Date.now();return (data.value?.items||[]).filter(i=>(!search.value||i.name.toLowerCase().includes(search.value.toLowerCase()))&&(filter.value==='all'||filter.value==='active'&&i.status==='ACTIVE'||filter.value==='planned'&&(i.status==='PLANNED'||i.status==='INTERESTED')||filter.value==='inactive'&&(i.status==='INACTIVE'||i.status==='CANCELLED')||filter.value==='upcoming'&&i.status==='ACTIVE'&&i.nextRenewal&&Date.parse(i.nextRenewal)<=now+7*86400000))})
const grouped=computed(()=>['ACTIVE','PLANNED','INTERESTED','INACTIVE'].map(status=>({status,label:statusLabel(status),items:visible.value.filter(s=>status==='INACTIVE'?['INACTIVE','CANCELLED'].includes(s.status):s.status===status)})).filter(g=>g.items.length))
const nextRenewal=computed(()=>(data.value?.items||[]).filter(i=>i.status==='ACTIVE'&&i.nextRenewal).sort((a,b)=>Date.parse(a.nextRenewal!)-Date.parse(b.nextRenewal!))[0])
const due=computed(()=>data.value?.items.filter(i=>i.status==='ACTIVE'&&i.nextRenewal&&Date.parse(i.nextRenewal)<=Date.now()+7*86400000)||[])
const empty=()=>({name:'',amount:'',interval:'MONTHLY',nextRenewal:new Date().toISOString().slice(0,10),status:'ACTIVE',category:'Other',usage:'UNKNOWN',importance:3,purpose:'',managementUrl:'',notes:''})
const form=ref(empty())
function inspect(item:External){selected.value=item;mode.value='details';open.value=true}
function edit(item?:External){mode.value='edit';editing.value=item?.id||'';formError.value='';form.value=item?{name:item.name,amount:String(item.amount/100),interval:item.interval,nextRenewal:item.nextRenewal?.slice(0,10)||'',status:item.status,category:item.category||'Other',usage:item.usage||'UNKNOWN',importance:item.importance??3,purpose:item.purpose||'',managementUrl:item.managementUrl,notes:item.notes}:empty();open.value=true}
async function save(){busy.value=true;formError.value='';try{const parsed=externalSubscriptionSchema.safeParse(form.value);if(!parsed.success){formError.value=parsed.error.issues.map(i=>i.message).join('; ');return}await api(`/external-subscriptions${editing.value?'/'+editing.value:''}`,{method:editing.value?'PUT':'POST',body:form.value});open.value=false;await refresh();toast.add({title:editing.value?'Subscription updated':'Subscription added',color:'success'})}catch(e){formError.value=errorMessage(e)}finally{busy.value=false}}
async function remove(){if(!removing.value)return;busy.value=true;try{await api(`/external-subscriptions/${removing.value.id}`,{method:'DELETE'});removing.value=null;open.value=false;await refresh()}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
function renewalLabel(value:string|null){if(!value)return 'Date not set';const days=Math.ceil((Date.parse(value)-Date.now())/86400000);return days<0?'Date passed — review renewal':days===0?'Renews today':`Renews in ${days} day${days===1?'':'s'}`}
</script>
<template>
 <div class="page space-y-6">
  <div class="flex flex-wrap justify-between items-start gap-4">
   <div><p class="eyebrow">Your collection</p><h1>Your subscriptions</h1><p class="text-sm text-muted mt-3">Know what you pay for. Keep what earns its place.</p></div>
   <UButton icon="i-lucide-plus" @click="edit()">Add subscription</UButton>
  </div>
  <UAlert v-if="error" color="error" :title="errorMessage(error)"><template #actions><UButton @click="refresh()">Try again</UButton></template></UAlert>
  <div v-if="!data?.items.length && status!=='pending' && !error" class="border-y border-dashed border-default py-12 text-center">
   <p class="font-medium">Nothing here yet</p>
   <UButton class="mt-5" icon="i-lucide-plus" @click="edit()">Add your first subscription</UButton>
  </div>
  <template v-if="data?.items.length || status==='pending'">
   <div class="advisor-metrics"><div class="p-5 bg-elevated/25"><p class="text-xs text-muted">Monthly spending</p><USkeleton v-if="status==='pending'" class="h-8 w-28 mt-3"/><p v-else class="text-2xl font-semibold mt-3 tabular-nums">{{money(data?.totals.monthly)}}</p><p class="text-xs text-dimmed mt-1">{{data?.totals.active||0}} active subscriptions</p></div><div class="p-5 bg-elevated/25"><p class="text-xs text-muted">Yearly estimate</p><p class="text-2xl font-semibold mt-3 tabular-nums">{{money(data?.totals.yearly)}}</p><p class="text-xs text-dimmed mt-1">Active plans only</p></div><div class="p-5 bg-elevated/25"><p class="text-xs text-muted">Next renewal</p><p class="text-2xl font-semibold mt-3">{{nextRenewal?date(nextRenewal.nextRenewal):'—'}}</p><p class="text-xs text-dimmed mt-1">{{nextRenewal?`${nextRenewal.name} · ${money(nextRenewal.amount)}`:'No upcoming renewals'}}</p></div></div>
   <div>
    <div class="flex flex-wrap justify-between items-center gap-3 py-3 border-y border-default"><div class="flex gap-1 flex-wrap"><UButton v-for="tab in filters" :key="tab.value" :color="filter===tab.value?'primary':'neutral'" :variant="filter===tab.value?'soft':'ghost'" size="sm" @click="filter=tab.value">{{tab.label}}<UBadge v-if="tab.value==='upcoming'&&due.length" size="xs" color="neutral" variant="subtle">{{due.length}}</UBadge></UButton></div><UInput v-model="search" icon="i-lucide-search" placeholder="Search subscriptions" aria-label="Search subscriptions" class="w-full sm:w-56"/></div>
    <div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left text-muted border-b border-default"><th class="py-3 pe-4 font-medium">Subscription</th><th class="py-3 pe-4 font-medium">Amount</th><th class="py-3 pe-4 font-medium hidden sm:table-cell">Next renewal</th><th class="py-3 pe-4 font-medium hidden md:table-cell">Use / importance</th><th class="py-3 pe-4 font-medium hidden md:table-cell">Status</th><th class="py-3"><span class="sr-only">Manage</span></th></tr></thead>
    <tbody v-for="group in grouped" :key="group.status" class="divide-y divide-default"><tr><td colspan="6" class="bg-muted text-xs font-semibold">{{group.label}} · {{group.items.length}}</td></tr><tr v-for="item in group.items" :key="item.id" class="hover:bg-elevated/40"><td class="py-3.5 pe-4"><button class="flex items-center gap-3 text-left" @click="inspect(item)"><UAvatar :alt="item.name" size="md"/><div><p class="font-medium">{{item.name}}</p><p class="text-xs text-muted mt-0.5">{{item.category||'Other'}} · {{item.interval.toLowerCase()}}</p></div></button></td><td class="py-3.5 pe-4 font-medium whitespace-nowrap tabular-nums">{{item.amount?money(item.amount):'₹0 — add amount'}}</td><td class="py-3.5 pe-4 hidden sm:table-cell"><p>{{date(item.nextRenewal)}}</p><p v-if="item.status==='ACTIVE'" class="text-xs text-muted mt-0.5">{{renewalLabel(item.nextRenewal)}}</p></td><td class="py-3.5 pe-4 hidden md:table-cell text-muted">{{(item.usage||'UNKNOWN').toLowerCase()}} · ★{{item.importance??3}}</td><td class="py-3.5 pe-4 hidden md:table-cell"><UBadge :color="item.status==='ACTIVE'?'success':'neutral'" variant="subtle" size="sm">{{statusLabel(item.status)}}</UBadge></td><td class="py-3.5 text-right"><UButton color="neutral" variant="ghost" icon="i-lucide-chevron-right" :aria-label="`Manage ${item.name}`" @click="inspect(item)"/></td></tr></tbody></table>
    <p v-if="!visible.length" class="py-12 text-center text-sm text-muted">No subscriptions match this view. <UButton variant="link" size="sm" @click="search='';filter='all'">Clear filters</UButton></p></div>
   </div>
  </template>
  <USlideover v-model:open="open" :title="mode==='details'?(selected?.name||'Subscription'):editing?'Edit subscription':'Add subscription'" >
   <template #body>
    <div v-if="mode==='details'&&selected" class="space-y-6"><div class="flex items-center gap-4"><UAvatar :alt="selected.name" size="xl"/><div><p class="text-3xl font-semibold">{{money(selected.amount)}}</p><p class="text-sm text-muted mt-1">Billed {{selected.interval.toLowerCase()}} · {{selected.category||'Other'}}</p></div></div>
     <dl class="divide-y divide-default text-sm"><div class="flex justify-between py-3.5"><dt class="text-muted">Status</dt><dd><UBadge :color="selected.status==='ACTIVE'?'success':'neutral'" variant="subtle">{{statusLabel(selected.status)}}</UBadge></dd></div><div class="flex justify-between py-3.5"><dt class="text-muted">Next renewal</dt><dd class="font-medium">{{date(selected.nextRenewal)}}</dd></div><div class="flex justify-between py-3.5"><dt class="text-muted">Reported use</dt><dd>{{(selected.usage||'UNKNOWN').toLowerCase()}}</dd></div><div class="flex justify-between py-3.5"><dt class="text-muted">Importance</dt><dd>★{{selected.importance??3}} / 5</dd></div><div v-if="selected.purpose" class="py-3.5"><dt class="text-muted mb-1">Purpose</dt><dd>{{selected.purpose}}</dd></div><div v-if="selected.notes" class="py-3.5"><dt class="text-muted mb-1">Notes</dt><dd class="whitespace-pre-wrap">{{selected.notes}}</dd></div></dl>
     <UButton v-if="selected.managementUrl" :to="selected.managementUrl" target="_blank" external block trailing-icon="i-lucide-external-link">Manage with {{selected.name}}</UButton></div>
    <form v-else id="subscription-form" class="space-y-5" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/>
     <UFormField label="Subscription name" required><UInput v-model="form.name" placeholder="e.g. Netflix" class="w-full" autofocus/></UFormField>
     <div class="grid grid-cols-2 gap-4"><UFormField label="Amount (₹)"><UInput v-model="form.amount" type="number" min="0" step="0.01" placeholder="0 — unknown is fine" class="w-full"/></UFormField><UFormField label="Billing cycle"><USelect v-model="form.interval" :items="[{label:'Monthly',value:'MONTHLY'},{label:'Yearly',value:'YEARLY'},{label:'Weekly',value:'WEEKLY'}]" class="w-full"/></UFormField></div>
     <UFormField label="Status" ><USelect v-model="form.status" :items="[{label:'Active',value:'ACTIVE'},{label:'Planned',value:'PLANNED'},{label:'Interested',value:'INTERESTED'},{label:'Inactive',value:'INACTIVE'}]" class="w-full"/></UFormField>
     <UFormField v-if="form.status==='ACTIVE'" label="Next renewal" required><UInput v-model="form.nextRenewal" type="date" class="w-full"/></UFormField>
     <div class="grid grid-cols-2 gap-4"><UFormField label="Category"><USelect v-model="form.category" :items="['Entertainment','AI','Education','Productivity','Development','Cloud','Design','Gaming','Music','Lifestyle','Other'].map(c=>({label:c,value:c}))" class="w-full"/></UFormField><UFormField label="How much do you use it?"><USelect v-model="form.usage" :items="[{label:'Not sure',value:'UNKNOWN'},{label:'A lot',value:'HIGH'},{label:'Sometimes',value:'MEDIUM'},{label:'Rarely',value:'LOW'}]" class="w-full"/></UFormField></div>
     <div class="grid grid-cols-2 gap-4"><UFormField label="Importance (1–5)"><UInput v-model.number="form.importance" type="number" min="1" max="5" class="w-full"/></UFormField><UFormField label="Purpose"><UInput v-model="form.purpose" placeholder="Why you keep it" class="w-full"/></UFormField></div>
     <UFormField label="Management link"><UInput v-model="form.managementUrl" type="url" placeholder="https://" class="w-full"/></UFormField>
     <UFormField label="Notes"><UTextarea v-model="form.notes" class="w-full"/></UFormField>
    </form>
   </template>
   <template #footer><div v-if="mode==='details'" class="flex justify-between w-full"><UButton color="error" variant="ghost" @click="removing=selected">Remove record</UButton><UButton icon="i-lucide-pencil" @click="edit(selected||undefined)">Edit details</UButton></div><div v-else class="flex justify-end gap-2 w-full"><UButton color="neutral" variant="ghost" @click="open=false">Cancel</UButton><UButton type="submit" form="subscription-form" :loading="busy">{{editing?'Save changes':'Add subscription'}}</UButton></div></template>
  </USlideover>
  <UModal :open="!!removing" title="Remove this subscription?" description="This removes the record only. Your plan with the provider stays unchanged." @update:open="v=>{if(!v)removing=null}"><template #footer><UButton color="neutral" variant="outline" @click="removing=null">Keep it</UButton><UButton color="error" :loading="busy" @click="remove">Remove record</UButton></template></UModal>
 </div>
</template>
